import React, { useState, useEffect } from 'react';
import { XCircle } from 'lucide-react';

function App() {
  const [amount, setAmount] = useState(2000);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [fundraisingData, setFundraisingData] = useState({
    currentAmount: 0,
    goalAmount: 45000,
    topContributors: [],
    recentSupporters: []
  });
  const [liveDonation, setLiveDonation] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const amountOptions = [500, 1000, 2000, 5000];

  useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const response = await fetch('/api/fundraising-data');
        const data = await response.json();
        setFundraisingData(data);
        setIsLoading(false);
      } catch (error) {
        console.error('Error fetching fundraising data:', error);
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    const simulatedSocket = setInterval(() => {
      if (Math.random() < 0.3) {
        const names = ['Rahul Joshi', 'Meera Shah', 'Anand Patel', 'Kavita Desai', 'Vijay Singh'];
        const amounts = [500, 1000, 1500, 2000, 3000, 5000];
        const randomName = names[Math.floor(Math.random() * names.length)];
        const randomAmount = amounts[Math.floor(Math.random() * amounts.length)];
        setLiveDonation({ name: randomName, amount: randomAmount, timestamp: new Date() });
        fetchUpdatedData();
        setTimeout(() => setLiveDonation(null), 5000);
      }
    }, 30000);

    return () => clearInterval(simulatedSocket);
  }, []);

  const fetchUpdatedData = async () => {
    try {
      const response = await fetch('/api/fundraising-data');
      const data = await response.json();
      setFundraisingData(data);
    } catch (error) {
      console.error('Error fetching updated data:', error);
    }
  };

  const handlePayment = async (e) => {
    e.preventDefault();
    if (!amount || !name || !email) {
      alert('Please fill in all required fields.');
      return;
    }

    try {
      const orderResponse = await fetch('/api/create-order', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount: amount * 100, name, email, message }),
      });

      const orderData = await orderResponse.json();
      if (orderData.error) {
        alert('Error creating order: ' + orderData.error);
        return;
      }

      const options = {
        key: "rzp_test_bv3a3THqFsS1Y9",
        amount: amount * 100,
        currency: "INR",
        name: "GT Bike Fundraiser",
        description: "Contribution to GT Bike fundraising campaign",
        order_id: orderData.id,
        handler: async function (response) {
          const verifyResponse = await fetch('/api/verify-payment', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
              amount, name, email, message
            }),
          });
          const verifyData = await verifyResponse.json();
          if (verifyData.success) {
            alert("Thank you for your contribution!");
            setName('');
            setEmail('');
            setMessage('');
            fetchUpdatedData();
          } else {
            alert("Payment verification failed. Please try again.");
          }
        },
        prefill: { name, email },
        theme: { color: "#1a73e8" }
      };

      const razorpay = new window.Razorpay(options);
      razorpay.open();

    } catch (error) {
      console.error('Payment error:', error);
      alert('There was an error processing your payment. Please try again.');
    }
  };

  const progressPercentage = Math.min((fundraisingData.currentAmount / fundraisingData.goalAmount) * 100, 100);

  return (
    <div className="bg-gray-50 min-h-screen pb-12">
      {/* Header */}
      <header className="bg-blue-600 text-white text-center py-12 px-4">
        <h1 className="text-4xl font-bold mb-2">Help Me Get My Dream GT Bike!</h1>
        <p className="text-xl">Support my goal and be a part of this journey</p>
      </header>

      {/* Main and Sidebar omitted for brevity */}
      {/* Paste the rest of your JSX here... */}
    </div>
  );
}

export default App;
